SELECT md.chembl_id AS compound_chembl_id, cs.canonical_smiles, r.compound_key, COALESCE(CAST(d.pubmed_id AS TEXT), d.doi) AS pubmed_id_or_doi, a.description AS assay_description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, td.chembl_id AS target_chembl_id, td.pref_name AS target_name, td.organism AS target_organism FROM molecule_dictionary md JOIN compound_structures cs ON cs.molregno = md.molregno JOIN compound_records r ON md.molregno = r.molregno JOIN docs d ON r.doc_id = d.doc_id JOIN activities act ON r.record_id = act.record_id JOIN assays a ON act.assay_id = a.assay_id JOIN target_dictionary td ON a.tid = td.tid WHERE td.chembl_id = 'CHEMBL2148' AND act.standard_type = 'IC50' ORDER BY md.chembl_id, cs.canonical_smiles, r.compound_key, COALESCE(CAST(d.pubmed_id AS TEXT), d.doi), a.description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, td.chembl_id, td.pref_name, td.organism
